package com.fitbite.service; import com.fitbite.dto.PreferenceDtos.*; import com.fitbite.entity.UserPreference; import com.fitbite.repository.UserPreferenceRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PreferenceService {private final CurrentUserService current;private final UserPreferenceRepository prefs;public PreferenceService(CurrentUserService current,UserPreferenceRepository prefs){this.current=current;this.prefs=prefs;} public ProfileResponse profile(){var u=current.get();var p=prefs.findByUserId(u.getId()).orElse(null);String role=u.getRoles().stream().findFirst().map(x->x.getName().name()).orElse("USER");return new ProfileResponse(u.getId(),u.getName(),u.getEmail(),role,p==null?null:p.getDietaryType(),p==null?null:p.getHealthGoal(),p==null?null:p.getMaxCalories(),p==null?null:p.getMinProtein(),p==null?null:p.getMaxCookingTime());} @Transactional public ProfileResponse update(PreferenceRequest r){var u=current.get();var p=prefs.findByUserId(u.getId()).orElse(UserPreference.builder().user(u).build());p.setDietaryType(r.dietaryType());p.setHealthGoal(r.healthGoal());p.setMaxCalories(r.maxCalories());p.setMinProtein(r.minProtein());p.setMaxCookingTime(r.maxCookingTime());prefs.save(p);return profile();}}
